export type TriageKind = "bug" | "question" | "feedback";

export type TriageSeverity = "low" | "medium" | "high" | "urgent";

export interface QueueIssue {
  identifier: string;
  url: string;
  title: string;
  description: string;
  reporter?: string;
}

export type TriageVerdict = {
  identifier: string;
  kind: TriageKind;
  severity: TriageSeverity;
  title: string;
  summary: string;
  nextStep: string;
  reporter?: string;
  duplicateOf?: string;
  needsInfo?: boolean;
};

export type TrackerIssue = {
  identifier: string;
  url: string;
};

export type QueueAction =
  | { op: "commented" }
  | { op: "prioritized"; severity: TriageSeverity }
  | { op: "duplicate_of"; of: string }
  | { op: "needs_info" };

export type TrackerResult =
  | { status: "not_connected" }
  | { status: "skipped"; reason: "eval" }
  | { status: "acted"; issue: TrackerIssue; actions: QueueAction[] }
  | { status: "failed"; message: string };

export type RecordTriageResult = {
  verdict: TriageVerdict;
  evaluatedAt: string;
  tracker: TrackerResult;
};

export type TrackerConfig = { kind: "none" } | { kind: "linear" | "jira"; connectionName: string };
